    "parentDashboard.activities": {
        parameters: {
            query?: {
                pet_id?: number | null;
                per_page?: number;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data: {
                            id: string;
                            activity_type: string;
                            value: string;
                            /** @description The child who did it (M2-01); null for system events. */
                            actor_user_id: string;
                            created_at: string | null;
                            /** @description Ignored warnings and M5-R02 behaviour events (accident, chewing) are negative. */
                            is_positive: boolean;
                        }[];
                        meta: {
                            current_page: number;
                            last_page: number;
                            total: number;
                        };
                    } | {
                        data: string[];
                        meta: {
                            /** @constant */
                            current_page: 1;
                            /** @constant */
                            last_page: 1;
                            total: number;
                        };
                    };
                };
            };
            401: components["responses"]["AuthenticationException"];
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        message: "Only parent profiles can access activities.";
                    };
                };
            };
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        message: "Pet not found in your family.";
                    };
                };
            };
            422: components["responses"]["ValidationException"];
        };
    };
    "parentDashboard.toggleHardStop": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: {
            content: {
                "application/json": components["schemas"]["HardStopRequest"];
            };
        };
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string} */
                        message: "Hard stop activated. Child app locked." | "Hard stop deactivated. Child app unlocked.";
                        pet_id: number;
                        is_hard_stopped: boolean;
                        /** @description false = the pet already was in the requested state (nothing written, no broadcast). */
                        changed: boolean;
                    };
                };
            };
            401: components["responses"]["AuthenticationException"];
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        message: "Only parent profiles can trigger hard stop.";
                    };
                };
            };
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        message: "No active pet session found.";
                    } | {
                        /** @constant */
                        message: "No child profile paired.";
                    };
                };
            };
            422: components["responses"]["ValidationException"];
        };
    };
